<script setup lang="ts">
import {onMounted,ref} from 'vue'
type Asset={id:number;batteryCode:string;modelCode:string;status:string;healthStatus:string;soc:number;soh:number;locationType:string|null;locationId:number|null}
const assets=ref<Asset[]>([]),loading=ref(false),error=ref('')
const labels:Record<string,string>={REGISTERED:'已建档',AVAILABLE:'可用',IN_SERVICE:'运营中',FROZEN:'已冻结',UNDER_REPAIR:'维修中',RETIRED:'已退役'}
async function load(){loading.value=true;error.value='';try{const r=await fetch('/api/v1/assets');if(!r.ok)throw new Error('资产服务请求失败');assets.value=(await r.json()).data}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
onMounted(load)
</script>
<template><el-container class="shell"><el-aside width="224px" class="side"><div class="brand"><b>⚡</b> Battery AMS</div><div class="section">资产运营</div><div class="nav active">▦　运营总览</div><div class="nav">▣　电池资产</div><div class="nav">▤　仓储管理</div><div class="nav">◷　工单中心</div><div class="nav">⌁　设备监控</div><div class="nav">◇　资产保全</div><div class="foot">BATTERY ASSET PLATFORM<br/>DEMO ENVIRONMENT</div></el-aside><el-container><el-header class="top"><span>新能源换电运营平台</span><el-tag type="success">开发演示环境</el-tag></el-header><el-main class="main"><div class="heading"><div><h1>运营总览</h1><p>电池资产分布与生命周期状态</p></div><el-button type="primary" :loading="loading" @click="load">刷新数据</el-button></div><el-alert v-if="error" :title="error+'；请确认 MySQL 和 asset-service 已启动'" type="warning" show-icon :closable="false"/><div class="kpis"><div class="kpi"><span>资产总量</span><strong>{{assets.length}}</strong><small>当前资产档案</small></div><div class="kpi"><span>可用电池</span><strong>{{assets.filter(x=>x.status==='AVAILABLE').length}}</strong><small>可进入调度流程</small></div><div class="kpi"><span>运营中</span><strong>{{assets.filter(x=>x.status==='IN_SERVICE').length}}</strong><small>已投放运营</small></div><div class="kpi"><span>风险/维修</span><strong class="warn">{{assets.filter(x=>['FROZEN','UNDER_REPAIR'].includes(x.status)).length}}</strong><small>需重点关注</small></div></div><section class="panel"><div class="panel-head"><div><h2>电池资产</h2><p>数据来自 asset-service / MySQL</p></div><el-tag>实时查询</el-tag></div><el-table :data="assets" v-loading="loading" stripe><el-table-column prop="batteryCode" label="电池编号" min-width="170"/><el-table-column prop="modelCode" label="型号" width="110"/><el-table-column label="SOC" width="150"><template #default="{row}"><el-progress :percentage="row.soc" :stroke-width="8"/></template></el-table-column><el-table-column label="SOH" width="100"><template #default="{row}">{{row.soh}}%</template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="row.status==='AVAILABLE'?'success':row.status==='FROZEN'?'danger':'info'">{{labels[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="位置" min-width="130"><template #default="{row}">{{row.locationType||'未分配'}} / {{row.locationId??'-'}}</template></el-table-column></el-table><el-empty v-if="!loading&&!assets.length&&!error" description="暂无资产数据"/></section><p class="disclaimer">Demo 数据为模拟数据，不连接真实 BMS 或换电设备。指标根据当前资产列表动态计算。</p></el-main></el-container></el-container></template>